package com.example.guitarmes.process;
import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status; import java.util.List; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import org.springframework.test.web.servlet.setup.MockMvcBuilders;
@ExtendWith(MockitoExtension.class) class ProcessWorkControllerTest { @Mock ProcessService service; MockMvc mvc; @BeforeEach void setUp(){mvc=MockMvcBuilders.standaloneSetup(new ProcessWorkController(service)).build();}
@Test void bulkStart_api() throws Exception { when(service.startProcesses(List.of(1L,2L),3L,"Worker")).thenReturn(List.of()); mvc.perform(post("/api/process/bulk/start").contentType(MediaType.APPLICATION_JSON).content("{\"guitarIds\":[1,2],\"processId\":3,\"workerName\":\"Worker\"}")).andExpect(status().isOk()); verify(service).startProcesses(List.of(1L,2L),3L,"Worker"); }
@Test void bulkEnd_api() throws Exception { when(service.endProcesses(List.of(4L,5L))).thenReturn(List.of()); mvc.perform(post("/api/process/bulk/end").contentType(MediaType.APPLICATION_JSON).content("{\"historyIds\":[4,5]}")).andExpect(status().isOk()); }
}
